  "privRights": "이용자의 권리",
  "noticeReopen": "저장소 안내",
  "noticeLabel": "브라우저 저장소 안내",
  "noticeText": "Cook은 사용 중인 요리 및 로그인 기능을 위해 브라우저 저장소를 사용합니다. 광고나 분석용 저장소는 추가되지 않습니다.",
  "noticeClose": "저장소 안내 닫기",
  "privDraftLabel": "초안 — 2026년 10월 28일 업데이트.",
  "privDraft": "계정 기능은 현재 테스트 중입니다. 아래의 운영자 및 서비스 정보는 공개 출시 전에 채워야 합니다.",
  "privWho1": "Cook은 [운영자의 법적 명칭 및 우편 주소]가 운영합니다. 개인정보 관련 문의와 요청은 [개인정보 문의 이메일]로 연락하세요. 이 정보는 가입을 열기 전에 채워야 합니다.",
  "privWhat1": "계정을 만들면 계정을 제공하고 보호하기 위해 이메일, 계정 식별자, 비밀번호 인증 기록, 인증 상태를 사용합니다. 비밀번호는 인증 제공업체가 안전한 해시로 처리하며, Cook은 읽을 수 있는 비밀번호를 저장하지 않습니다. 모든 기기에서 설정을 복원할 수 있도록 주방 배치, 선택한 언어, 테마, 측정 단위를 저장합니다. 계정에는 이메일과 비밀번호가 필요하며, 레시피는 계정 없이도 볼 수 있습니다.",
  "privWhat2": "계정과 설정의 처리는 요청하신 계정 서비스를 제공하는 데 필요합니다(GDPR 제6조 제1항 (b)). 보안 및 악용 방지를 위한 제한적인 기록은 필요성과 이익 형량을 조건으로 정당한 이익(제6조 제1항 (f))에 근거해 처리될 수 있습니다. 인증 메일과 비밀번호 재설정 메일은 마케팅이 아닌 서비스 메시지입니다. 계정 기능은 광고나 분석을 추가하지 않습니다.",
  "privStorage1": "Cook은 sessionStorage를 사용해 같은 탭 안의 페이지 사이에서 주방, 요리 진행 상황, 선택 내용을 이어 줍니다. 로그인한 경우 인증 세션도 저장합니다. 브라우저는 보통 탭 세션이 끝나면 이를 지우지만, 브라우저의 세션 복원 기능으로 남아 있을 수 있습니다. 로그아웃하면 Cook의 탭 데이터가 지워집니다. 저장소 안내를 닫은 상태는 해당 탭에서만 기억됩니다. Cook 자체 스크립트는 쿠키를 설정하지 않습니다. 호스팅 또는 서비스 제공업체가 자체적인 보안 처리를 할 수 있으며, 이는 출시 전에 문서화해야 합니다.",
  "privStorage2": "저장소 안내의 확인 버튼과 닫기 버튼은 안내를 닫기만 합니다. 분석, 광고 또는 기타 선택적 추적을 허용하지 않습니다. 앞으로 필수적이지 않은 저장소를 사용하려면 시작 전에 별도의 선택이 필요하며, 거부와 철회도 똑같이 쉬워야 합니다.",
  "privOther1": "현재 레시피 목록의 음성 기능은 음성 인식 언어를 고르기 위해 IP 주소를 이용해 country.is에 대략적인 국가를 요청합니다. 마이크 인식을 사용하면 브라우저가 음성을 해당 브라우저의 음성 인식 서비스 제공업체로 보낼 수 있습니다. 재료는 직접 입력할 수도 있습니다. 이 제공업체들과 그 정책, 그리고 이 기능들의 법적 근거는 공개 출시 전에 검토해야 합니다.",
  "privProviders1": "예정된 계정 제공업체: Supabase(관리형 PostgreSQL 및 인증), EU 내에서 선택한 데이터베이스 지역 사용. 이메일 제공업체: [제공업체]. 웹사이트 호스팅: [제공업체]. 운영자는 실제 제공업체, 처리 위탁 계약, 재수탁자, 로그 저장 위치 및 EEA 외부로의 이전 여부를 확인해야 합니다. EU 데이터베이스 지역이라는 사실만으로 국외 이전이 배제되지는 않습니다. 해당하는 경우 적용되는 적정성 결정 또는 계약상 보호 조치와 그 사본을 받는 방법을 명시하세요.",
  "privRetention1": "계정 설정은 계정이 활성 상태인 동안 보관됩니다. 위의 개인정보 연락처를 통해 삭제를 요청할 수 있습니다. 출시 전에 운영자는 삭제 요청 처리 절차, 미인증 계정의 만료, 보안 로그 및 백업의 보관 기간을 정해야 합니다. 삭제된 데이터는 문서화된 백업 보관 기간이 끝날 때까지 접근이 제한된 백업에 남아 있을 수 있습니다.",
  "privRights1": "적용되는 조건에 따라 열람, 정정, 삭제, 처리 제한 또는 이동을 요청하거나, 정당한 이익에 근거한 처리에 이의를 제기할 수 있습니다. 위의 운영자에게 연락하세요. 요청에는 보통 한 달 이내에 답변하며, 법적으로 기한을 연장하는 경우 그 이유를 설명합니다. 헝가리의 NAIH(naih.hu)를 포함한 감독 기관에 민원을 제기할 수 있습니다. Cook은 법적 효과나 이와 유사한 중대한 영향을 미치는 자동화된 결정에 계정 설정을 사용하지 않습니다.",
