  "Put the diced guanciale into the COLD pan, then turn the burner to LOW. Lean guanciale? Add 1 tsp neutral oil first.": "깍둑썬 관찰레를 ‘차가운’ 팬에 넣은 다음 불을 ‘약한 불’로 켜세요. 관찰레가 기름기가 적다면 먼저 식용유 1작은술을 두르세요.",
