  "Pasta into the pan": "파스타를 팬에",
  "With tongs, move the spaghetti straight into the pan. Add pasta water a ladle at a time while tossing, until creamy.": "집게로 스파게티를 바로 팬에 옮기세요. 버무리면서 면수를 한 국자씩 넣어 크리미하게 만드세요.",
  "Glossy, creamy coating": "윤기 있고 크리미하게 코팅됨",
  "Let it calm down": "잠시 식히기",
  "Wait until the pan has just stopped sizzling but is still warm. Too hot = scrambled eggs.": "팬에서 지글거리는 소리가 막 멈추고 아직 따뜻할 때까지 기다리세요. 너무 뜨거우면 스크램블드에그가 돼요.",
