  "nokedliszaggató": "노케들리사가토",
  "Scraped off a wet board with a knife": "젖은 도마에서 칼로 긁어내기",
  "cut into thigh and drumstick": "윗다리와 북채로 나눔",
  "Cut the chicken": "닭 나누기",
  "Cut the legs at the joint into thighs and drumsticks. Pat dry and sprinkle with the salt and pepper.": "닭다리를 관절에서 잘라 윗다리와 북채로 나누세요. 물기를 닦고 소금과 후추를 뿌리세요.",
  "Cut and seasoned": "나누고 밑간함",
  "Melt the lard in the saucepan and cook the onion until soft and golden.": "소스팬에 라드를 녹이고 양파가 부드럽고 노릇해질 때까지 볶으세요.",
  "Take the pan off the heat, stir in the paprika and add a splash of the water at once so the paprika doesn't burn.": "소스팬을 불에서 내리고 파프리카 가루를 섞은 뒤 타지 않도록 바로 물을 조금 넣으세요.",
  "Add the chicken and turn it in the paprika. Add the tomato, the pepper and the rest of the water.": "닭을 넣고 파프리카에 굴리세요. 토마토, 피망, 남은 물을 넣으세요.",
  "Chicken coated": "닭에 고루 묻음",
  "Cover and simmer gently, turning the chicken once, until it is tender and comes away from the bone.": "뚜껑을 덮고 약하게 끓이되 닭을 한 번 뒤집어, 부드러워지고 뼈에서 떨어질 때까지 익히세요.",
  "Tender at the bone": "뼈에서 떨어짐",
  "Make the nokedli dough": "노케들리 반죽 만들기",
  "Mix the flour, the eggs, the salt and the water into a thick, sticky dough that drops slowly from the spoon. Beat until smooth.": "밀가루, 달걀, 소금, 물을 섞어 숟가락에서 천천히 떨어지는 되직하고 끈적한 반죽을 만드세요. 매끄러워질 때까지 저으세요.",
  "Thick, sticky, smooth": "되직하고 끈적하며 매끄러움",
  "Let the dough rest so it becomes smooth.": "반죽을 휴지시켜 매끄럽게 하세요.",
  "Make the nokedli": "노케들리 만들기",
  "Set the spaetzle maker over the boiling water, fill the box with dough and slide it back and forth. Work in 2 or 3 batches.": "끓는 물 위에 스패츨 메이커를 올리고 통에 반죽을 채워 앞뒤로 미세요. 2–3번에 나눠 하세요.",
  "Dough all in the water": "반죽이 모두 물속에",
  "Cook until they float": "떠오를 때까지 삶기",
  "Boil until the nokedli float, then 1 more minute.": "노케들리가 떠오르면 1분 더 삶으세요.",
  "Drain and toss": "물기 빼고 버무리기",
  "Drain the nokedli in a colander, rinse quickly with hot water and toss with the butter or oil so they don't stick.": "노케들리를 체에 밭치고 뜨거운 물에 재빨리 헹군 뒤, 붙지 않도록 버터나 기름에 버무리세요.",
  "Loose, not sticky": "서로 붙지 않음",
  "Whisk the sour cream and the flour smooth in a bowl.": "볼에 사워크림과 밀가루를 매끄럽게 섞으세요.",
  "Thicken the sauce": "소스 걸쭉하게 하기",
  "Lift out the chicken. Stir a ladle of the hot sauce into the sour cream mix, then stir it all into the pan. Simmer 3 minutes and put the chicken back.": "닭을 건지세요. 뜨거운 소스 한 국자를 사워크림 혼합물에 섞고 모두 소스팬에 다시 부으세요. 3분 끓인 뒤 닭을 다시 넣으세요.",
  "Creamy, coats the spoon": "크리미하고 숟가락에 묻음",
  "Serve the chicken and plenty of sauce with the nokedli.": "닭에 소스를 듬뿍 곁들이고 노케들리와 함께 내세요.",
  "Cut the chicken · Chop the vegetables": "닭 나누기 · 채소 썰기",
  "Soften the onion … Thicken the sauce": "양파 부드럽게 볶기 … 소스 걸쭉하게 하기",
