  "Wet the chopping board and spread some dough near its edge. Hold it over the pot and scrape thin strips into the boiling water with a wet knife, dipping the knife in the water as you go. Work in batches.": "도마를 적시고 가장자리 근처에 반죽을 조금 펴세요. 냄비 위에 들고 젖은 칼로 가늘게 긁어 끓는 물에 떨어뜨리고, 칼은 수시로 물에 적시세요. 여러 번에 나눠 하세요.",
