  "Peppers soft": "피망이 부드러움",
  "Add the tomatoes, the salt and the sugar. Simmer uncovered until the tomatoes fall apart and most of the liquid is gone.": "토마토, 소금, 설탕을 넣으세요. 토마토가 뭉개지고 수분이 대부분 날아갈 때까지 뚜껑을 열고 끓이세요.",
  "Thick, saucy": "걸쭉하고 진함",
