  "Whisk the whites to soft peaks, then add half the sugar a little at a time and whisk until stiff and glossy.": "흰자를 부드러운 뿔이 생길 때까지 휘핑한 뒤 설탕 절반을 조금씩 넣으며 단단하고 윤기 나는 뿔이 생길 때까지 휘핑하세요.",
