  "Divide the batter in two bowls. Fold the ground walnuts into one and the cocoa into the other.": "반죽을 두 볼에 나누세요. 한쪽에는 간 호두를, 다른 쪽에는 코코아를 살살 섞으세요.",
  "Two batters": "반죽 두 가지",
