  "Fold a ridge in the middle of the baking paper and spread the walnut batter on one half, the cocoa batter on the other, about 1 cm thick.": "유산지 가운데를 접어 칸을 만들고 호두 반죽은 한쪽에, 코코아 반죽은 다른 쪽에 약 1 cm 두께로 펴세요.",
  "Evenly spread": "고르게 폄",
