  "Custard base": "크림 베이스",
  "Whisk the yolks, the sugar and the flour smooth with a few spoons of the milk. Heat the rest of the milk in the saucepan until it steams.": "노른자, 설탕, 밀가루를 우유 몇 숟가락과 매끄럽게 섞으세요. 남은 우유는 소스팬에서 김이 날 때까지 데우세요.",
  "Smooth base, milk steaming": "매끄러운 베이스, 김 나는 우유",
