  "Tear the sponges into rough pieces. In a deep dish, layer the walnut sponge, half the syrup, half the custard, half the raisins and walnuts; then the cocoa sponge, the rest of the syrup, raisins and walnuts, and finish with the custard.": "스펀지를 큼직하게 찢으세요. 깊은 그릇에 호두 스펀지, 시럽 절반, 크림 절반, 건포도와 호두 절반을 깔고, 이어서 코코아 스펀지, 남은 시럽, 건포도, 호두를 올린 뒤 크림으로 마무리하세요.",
  "Cover and chill for at least 4 hours; overnight is best.": "덮어서 최소 4시간 냉장하세요. 하룻밤이 가장 좋습니다.",
